import { toast } from 'sonner';
import { Button } from '@levain/ui-react';

function MyComponent() {
  return (
    <Button onClick={() => toast('This is a toast notification')}>
      Show Toast
    </Button>
  );
}

// Base/Default toast
toast('This is a standard toast.');

// Success toast
toast.success('Operation completed successfully');

// Error toast
toast.error('An error occurred');

// Warning toast
toast.warning('Please check the details.');

// Info toast
toast.info('Here is some information.');

// Loading toast
toast.loading('Processing your request...');

// Promise toast (shows loading, then success/error)
toast.promise(fetchData(), {
  loading: 'Loading data...',
  success: (data) => `Loaded ${data.length} items`,
  error: 'Failed to load data',
});

// Custom component toast
toast(
  <div className="flex items-center">
    {/* <Icon className="mr-2" /> */}
    <span>Custom toast content</span>
  </div>
);

